#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const registry = require('../server/services/gateway/metricsRegistry');

const OUTPUT_PATH = path.join(__dirname, '..', 'server', 'ops', 'observability', 'prometheus', 'prometheus.yml');
const HEADER = `# GENERATE | DO NOT EDIT MANUALLY
# This file is generated by scripts/sync-prom-metrics.js using the service metrics registry.
# Run \`node scripts/sync-prom-metrics.js\` after updating the registry.\n\n`;

function buildPrometheusConfig(entries) {
  const lines = [
    'global:',
    '  scrape_interval: 15s',
    '  evaluation_interval: 15s',
    '',
    'scrape_configs:'
  ];

  entries.filter((entry) => entry.enabled).forEach((entry) => {
    lines.push(`  - job_name: ${entry.name}`);
    lines.push(`    metrics_path: ${entry.path}`);
    lines.push('    static_configs:');
    lines.push('      - targets:');
    lines.push(`          - ${entry.name}:${entry.port}`);
  });

  return lines.join('\n');
}

function main() {
  const entries = registry.list();
  const config = buildPrometheusConfig(entries);
  fs.mkdirSync(path.dirname(OUTPUT_PATH), { recursive: true });
  fs.writeFileSync(OUTPUT_PATH, `${HEADER}${config}\n`);
  console.log(`Prometheus configuration written to ${OUTPUT_PATH}`);
}

main();
